def _dump(node):
    return ast.dump(node,include_attributes=False)


def _code_shape(code):
    return tuple(getattr(code,name)for name in ('co_code','co_names','co_varnames',
        'co_argcount','co_posonlyargcount','co_kwonlyargcount','co_flags',
        'co_freevars','co_cellvars'))+(tuple(_code_shape(value)if type(value)is CodeType
            else value for value in code.co_consts),)


def _code_at(code,name):
    values=[value for value in code.co_consts if type(value)is CodeType and value.co_name==name]
    if len(values)!=1:raise ValueError('one complete lexical early-panel owner required: '+name)
    return values[0]


def _context(module):
    tree=ast.parse(inspect.getsource(module),filename=module.__file__)
    return tree,compile(tree,module.__file__,'exec',dont_inherit=True)


def _function(module,name,code):
    function=getattr(module,name)
    if (type(function)is not FunctionType or function.__globals__ is not vars(module)
            or function.__module__!=module.__name__ or function.__qualname__!=name
            or function.__closure__ is not None or function.__code__.co_freevars
            or _code_shape(function.__code__)!=_code_shape(_code_at(code,name))):
        raise ValueError('actual complete-module early-panel function required: '+name)
    return function


def _panel_tree(original):
    """Finite named-call changes only, with full original FN/module inverses."""
    result=copy.deepcopy(original);inverses={}
    for index,node in enumerate(original.body):
        if not isinstance(node,ast.FunctionDef)or node.name not in EXPECTED_SOURCE:continue
        if _dump(node)!=_dump(ast.parse(EXPECTED_SOURCE[node.name]).body[0]):
            raise ValueError('complete reviewed early Main source changed: '+node.name)
        if any(isinstance(value,(ast.Yield,ast.YieldFrom))for value in ast.walk(node)):
            raise ValueError('original complete early-panel Main must remain synchronous')
        counts={'_campaign_call_fields':0,'_campaign_tail_fields':0};changes=[]

        class Lift(ast.NodeTransformer):
            def visit_Call(self,item):
                item=self.generic_visit(item)
                if isinstance(item.func,ast.Name)and item.func.id in counts:
                    name=item.func.id;counts[name]+=1;before=copy.deepcopy(item)
                    item.func.id=('_early_panel_call'if name=='_campaign_call_fields'else '_early_panel_tail')
                    after=ast.copy_location(ast.YieldFrom(value=item),item)
                    changes.append((before,copy.deepcopy(after)));return after
                return item

        derived=Lift().visit(copy.deepcopy(node))
        expected={'_campaign_call_fields':CALL_COUNTS[node.name],
            '_campaign_tail_fields':int(node.name=='request_affordable_action_panel_fields')}
        if counts!=expected:raise ValueError('exact early-panel CALL/tail syntax count required')
        remaining=list(changes)

        class Inverse(ast.NodeTransformer):
            def visit_YieldFrom(self,item):
                for position,(before,after)in enumerate(remaining):
                    if _dump(item)==_dump(after):remaining.pop(position);return copy.deepcopy(before)
                raise ValueError('unadmitted early-panel cooperative expression')

        inverse=Inverse().visit(copy.deepcopy(derived))
        if remaining or _dump(inverse)!=_dump(node):raise ValueError('entire early-panel FN inverse differs')
        result.body[index]=derived;inverses[index]=inverse
    if len(inverses)!=9:raise ValueError('all nine complete early-panel Main owners required')
    restored=copy.deepcopy(result)
    for index,node in inverses.items():restored.body[index]=node
    if _dump(restored)!=_dump(original):raise ValueError('entire original Main module inverse differs')
    return ast.fix_missing_locations(result)


def _class_bindings(module,cls,name,tree,code):
    nodes=[node for node in tree.body if isinstance(node,ast.ClassDef)and node.name==name]
    if len(nodes)!=1 or getattr(module,name)is not cls:raise ValueError('one actual early-panel provider/base class required')
    class_code=_code_at(code,name);result=[]
    for node in nodes[0].body:
        if not isinstance(node,ast.FunctionDef):continue
        descriptor=vars(cls).get(node.name)
        function=descriptor.__func__ if type(descriptor)is staticmethod else descriptor
        if (type(function)is not FunctionType or function.__globals__ is not vars(module)
                or function.__qualname__!=name+'.'+node.name
                or _code_shape(function.__code__)!=_code_shape(_code_at(class_code,node.name))):
            raise ValueError('actual complete-module early-panel class method required: '+node.name)
        result.append((cls,node.name,descriptor,function,function.__code__))
    return result


class EarlyPanelScenePrograms(BattleScenePrograms):
    """Nine exact indexed Main3CE parents; no global dispatcher replacement."""
    def __init__(self,state):
        if (BattleScenePrograms is not battle.BattleScenePrograms
                or EarlyPanelScenePrograms.__bases__!=(BattleScenePrograms,)):
            raise ValueError('unchanged actual BattleScenePrograms base required')
        own=inspect.getmodule(EarlyPanelScenePrograms)
        if own is None or vars(own)is not globals():raise ValueError('actual early-panel module required')
        self._panel_classes=(BattleScenePrograms,EarlyPanelScenePrograms,own)
        self._panel_class_methods=[];self._panel_utilities=[]
        for module,cls,name in ((battle,BattleScenePrograms,'BattleScenePrograms'),
                (own,EarlyPanelScenePrograms,'EarlyPanelScenePrograms')):
            tree,code=_context(module)
            self._panel_class_methods+=_class_bindings(module,cls,name,tree,code)
            for node in tree.body:
                if isinstance(node,ast.FunctionDef):
                    function=_function(module,node.name,code)
                    self._panel_utilities.append((module,node.name,function,function.__code__))
        super().__init__(state)
        self.panel_originals={};self.panel_imports=[]
        main=importlib.import_module('tools.high_level_main_flows.business_main')
        tree,code=_context(main);nodes={n.name:n for n in tree.body if isinstance(n,ast.FunctionDef)}
        for name,expected in EXPECTED_SOURCE.items():
            if name not in nodes or _dump(nodes[name])!=_dump(ast.parse(expected).body[0]):
                raise ValueError('entire original early-panel Main source differs: '+name)
            function=_function(main,name,code)
            self.panel_originals[main.__name__,name]=(main,function,function.__code__)
        derived=compile(_panel_tree(tree),main.__file__,'exec',dont_inherit=True)
        self.panel_namespace=dict(vars(main))
        self.panel_bindings={'_early_panel_call':self.views['main','_campaign_call_fields'],
            '_early_panel_tail':self._clear_tail}
        for name,value in self.panel_bindings.items():
            if name in self.panel_namespace:raise ValueError('private early-panel alias cannot shadow original business')
            self.panel_namespace[name]=value
        self.panel_views={}
        for name in EXPECTED_SOURCE:
            original=getattr(main,name)
            view=FunctionType(_code_at(derived,name),self.panel_namespace,name,original.__defaults__,None)
            view.__kwdefaults__=original.__kwdefaults__;view.__annotations__=dict(original.__annotations__)
            if not inspect.isgeneratorfunction(view):raise ValueError('whole early-panel generator required')
            self.panel_views[name]=view
        self._panel_view_owners={name:(view,view.__code__)for name,view in self.panel_views.items()}
        for path,sources in REUSED_SOURCE.items():
            module=importlib.import_module(path);tree,code=_context(module)
            nodes={n.name:n for n in tree.body if isinstance(n,ast.FunctionDef)}
            for name,expected in sources.items():
                if name not in nodes or _dump(nodes[name])!=_dump(ast.parse(expected).body[0]):
                    raise ValueError('entire mature early-panel child/helper source differs: '+name)
                function=_function(module,name,code)
                self.panel_originals[path,name]=(module,function,function.__code__)
            for node in tree.body:
                if not isinstance(node,ast.ImportFrom):continue
                for alias in node.names:
                    name=alias.asname or alias.name;value=getattr(module,name)
                    if type(value)is FunctionType:self.panel_imports.append((module,name,value,value.__code__))
        self.panel_admissions=dict(confidence='confirmed_source_candidate_runtime_unverified',
            whole_Main_views=9,call_propagations=sum(CALL_COUNTS.values()),tail_propagations=1,
            outer_return=0x3CE,direct_clear_call=(0x68CE,0xB230),clear_tail=0x60C,
            refresh_returns=REFRESH_RETURNS,new_wait_types=0,new_device_clock_or_budget=False)

    def require_current(self,state):
        base,cls,module=self._panel_classes
        if (BattleScenePrograms is not base or battle.BattleScenePrograms is not base
                or EarlyPanelScenePrograms is not cls or module.EarlyPanelScenePrograms is not cls
                or cls.__bases__!=(base,)):
            raise ValueError('actual early-panel provider/base class changed')
        for owner,name,descriptor,function,code in self._panel_class_methods:
            if vars(owner).get(name)is not descriptor or function.__code__ is not code:
                raise ValueError('actual complete early-panel/base method changed: '+name)
        for owner,name,function,code in self._panel_utilities:
            if getattr(owner,name)is not function or function.__code__ is not code:
                raise ValueError('actual complete early-panel source helper changed: '+name)
        super().require_current(state)
        if not hasattr(self,'panel_originals'):return
        for (path,name),(module,function,code)in self.panel_originals.items():
            if getattr(module,name)is not function or function.__code__ is not code:
                raise ValueError('actual complete early-panel business owner changed: '+name)
        for module,name,function,code in self.panel_imports:
            if getattr(module,name)is not function or function.__code__ is not code:
                raise ValueError('actual mature early-panel imported alias changed: '+name)
        if self.panel_views.keys()!=self._panel_view_owners.keys():raise ValueError('finite early-panel whole view set changed')
        for name,(view,code)in self._panel_view_owners.items():
            if self.panel_views[name]is not view or view.__code__ is not code:
                raise ValueError('whole early-panel private CodeType changed: '+name)
        for name,value in self.panel_bindings.items():
            if self.panel_namespace.get(name)is not value:raise ValueError('private early-panel source binding changed: '+name)

    def _forward_device(self,program):
        first=True;returned=None
        try:
            while True:
                self.require_current(self.state)
                try:waiting=next(program)if first else program.send(returned)
                except StopIteration as finished:return finished.value
                first=False
                if type(waiting)is not GameplaySceneWait or waiting.state is not self.state or waiting.needs_interrupt:
                    raise ValueError('only an existing exact same-Scene device wait is admitted here')
                waiting.validate();returned=yield waiting
                self.require_current(self.state)
                if returned is not waiting.frame or self.state.sr!=waiting.status_word:
                    raise ValueError('explicit device progress must preserve actual frame and full SR')
        finally:program.close()

    def _clear_tail(self,state,frame,target):
        self.require_current(state)
        if target!=0x60C:raise MovementContinuationBoundary(target,frame,'only the actual denied-panel060C BRA tail is admitted')
        # The original Main's incoming3CE stays live. This is not a CALL.
        return (yield from self._forward_device(
            self.battle_views['services','clear_scene_video_and_state_fields'](SceneRefreshMemory(state),frame)))

    def _campaign_child(self,state,frame,target,continuation):
        self.require_current(state)
        if (target,continuation)==(0x68CE,0xB230):
            return (yield from self._forward_device(
                self.battle_views['services','clear_video_sprite_plane_fields'](SceneRefreshMemory(state),frame)))
        if target==0xAF48 and continuation in REFRESH_RETURNS:
            return (yield from self._refresh(SceneRefreshMemory(state),frame))
        return (yield from super()._campaign_child(state,frame,target,continuation))

    def _display_child(self,state,frame,target,continuation):
        self.require_current(state)
        if target in MAIN_ENTRIES:
            if continuation!=0x3CE:raise MovementContinuationBoundary(target,frame,'early Main parent requires actual3CE')
            return (yield from self.panel_views[MAIN_ENTRIES[target]](state,frame))
        return (yield from super()._display_child(state,frame,target,continuation))

    def main_scene_call(self,state,frame,target,continuation):
        if target not in MAIN_ENTRIES:return (yield from super().main_scene_call(state,frame,target,continuation))
        self.require_current(state)
        if self._started or continuation!=0x3CE:raise ValueError('one actual indexed early-panel Main invocation required')
        self._started=True
        return (yield from self.views['display','display_call_fields'](state,frame,target,continuation))
